1	/**
2	 * @module features/tv-dashboard/model/types
3	 *
4	 * Tipos de domínio do Dashboard de Crise (painel TV `/tv`).
5	 * Spec: `.harness/spec/dashboard-tv-crise/spec.md`.
6	 */
7	
8	/**
9	 * Canal de origem do dado de venda de uma unidade.
10	 *
11	 * - `degust-live`: lojas integradas ao POS Degust (flash-vendas ao vivo).
12	 *   O conjunto de lojas vem da tabela `degust_stores` em runtime (hoje:
13	 *   Lago Sul, Águas Claras, BSB Shopping) — nunca hardcoded.
14	 * - `linx-lagged`: lojas no POS Linx sem integração live — usamos o último
15	 *   dia disponível em `historico_vendas` com selo "até DD/MM".
16	 * - `factory`: fábrica (sem venda; card de produção/expedição).
17	 */
18	export type TvSalesChannel = 'degust-live' | 'linx-lagged' | 'factory';
19	
20	/** Estado RAG (red/amber/green) de um card de unidade. */
21	export type TvRagStatus = 'ok' | 'amber' | 'red';
22	
23	/**
24	 * Filtro global de período do painel (v3): hoje / semana corrente
25	 * (segunda→hoje) / mês corrente (dia 1º→hoje). Perdas, compras e seus
26	 * comparativos respeitam o filtro; vendas dos cards são SEMPRE de hoje.
27	 */
28	export type TvPeriod = 'today' | 'week' | 'month';
29	
30	/** Range de dias FECHADO [from, to], ambos YYYY-MM-DD no fuso local. */
31	export interface TvDateRange {
32	  from: string;
33	  to: string;
34	}
35	
36	/** Severidade de um item de estoque crítico (zerado pesa mais). */
37	export type TvCriticalSeverity = 'zerado' | 'abaixo-minimo';
38	
39	/**
40	 * Item de estoque crítico NOMEADO de uma unidade, já ordenável por
41	 * severidade (zerados ⛔ primeiro; depois ⚠ por % faltante).
42	 */
43	export interface TvCriticalItem {
44	  nome: string;
45	  quantidade: number;
46	  minima: number;
47	  severity: TvCriticalSeverity;
48	}
49	
50	/** Linha do feed de movimentações nomeado ("AGORA" / drill-down). */
51	export interface TvRecentMove {
52	  /** Hora local HH:mm derivada de `data_movimentacao` ("—" se ausente). */
53	  hora: string;
54	  /** Timestamp cru ISO da movimentação (ordenar/tooltip), ou null. */
55	  timestamp: string | null;
56	  /** Tipo cru (`entrada` | `saida` | outros valores da tabela). */
57	  tipo: string;
58	  produtoNome: string;
59	  quantidade: number;
60	}
61	
62	/** Perdas agregadas (tabela `perdas`) no período do filtro global. */
63	export interface TvPerdasSummary {
64	  /** R$ somado de `valor_estimado` (linhas sem valor contam como 0). */
65	  valor: number;
66	  /** Número de registros de perda no período. */
67	  itens: number;
68	  /** Delta % vs período anterior equivalente (null sem base positiva). */
69	  deltaPct: number | null;
70	}
71	
72	/** Compras (NFs) agregadas — usado no drill-down por loja. */
73	export interface TvComprasSummary {
74	  valor: number;
75	  deltaPct: number | null;
76	}
77	
78	/** Marketing (ações de `acoes_marketing`) agregado no período do filtro global. */
79	export interface TvMarketingSummary {
80	  /** R$ somado de `valor_estimado` das ações de marketing. */
81	  valor: number;
82	  /** Número de ações de marketing no período. */
83	  acoes: number;
84	  /** Delta % vs período anterior equivalente (null sem base positiva). */
85	  deltaPct: number | null;
86	}
87	
88	/** Linha detalhada de perda (drill-down por loja). */
89	export interface TvPerdaDetail {
90	  id: number;
91	  produtoNome: string;
92	  quantidade: number;
93	  unidade: string | null;
94	  motivo: string;
95	  /** R$ estimado da perda (0 quando não informado). */
96	  valor: number;
97	  /** Timestamp ISO de `data_identificacao`, ou null. */
98	  data: string | null;
99	}
100	
101	/** Linha detalhada de NF de compra (drill-down por loja). */
102	export interface TvNotaFiscalDetail {
103	  id: number;
104	  numero: string;
105	  fornecedor: string;
106	  valor: number;
107	  /** Data de emissão `data_nota` (YYYY-MM-DD — campo canônico no app). */
108	  dataNota: string;
109	}
110	
111	/** Nível de frescor de um dado-fonte em relação ao intervalo esperado. */
112	export type TvFreshnessLevel = 'fresh' | 'stale' | 'very-stale';
113	
114	/** Severidade de uma exceção exibida na faixa inferior. */
115	export type TvExceptionSeverity = 'red' | 'amber';
116	
117	/** Tipo de exceção exibida na faixa inferior. */
118	export type TvExceptionKind =
119	  | 'stock-out'
120	  | 'stock-low'
121	  | 'no-movement'
122	  | 'stale-data';
123	
124	/** Janela de funcionamento usada no pró-rata da meta (hora local 0-24). */
125	export interface TvBusinessHours {
126	  start: number;
127	  end: number;
128	}
129	
130	/** Snapshot de vendas de uma unidade (live ou defasado). */
131	export interface TvSalesSnapshot {
132	  /** Valor vendido em R$ no dia de referência. */
133	  valor: number;
134	  /** Número de cupons/transações (null quando a fonte não informa). */
135	  cupons: number | null;
136	  /** Ticket médio em R$ (null quando a fonte não informa). */
137	  ticketMedio: number | null;
138	  /** Dia a que o dado se refere (YYYY-MM-DD). Para canal live = hoje. */
139	  dataReferencia: string;
140	  /** true quando o dado é ao vivo (flash-vendas); false = defasado. */
141	  isLive: boolean;
142	  /** Caixa aberto agora (apenas canal live; null quando não se aplica). */
143	  caixaAberto: boolean | null;
144	  /** Timestamp informado pela fonte da última atualização (ISO, ou null). */
145	  atualizadoEm: string | null;
146	}
147	
148	/** Contadores de alerta de estoque de uma unidade (apenas produtos ativos). */
149	export interface TvStockAlertSummary {
150	  /** Itens com quantidade ≤ 0 e mínimo definido (positivo). */
151	  zerados: number;
152	  /** Itens com quantidade entre 0 exclusivo e o mínimo. */
153	  abaixoMinimo: number;
154	}
155	
156	/** Item de estoque em alerta (detalhe usado na faixa de exceções). */
157	export interface TvStockAlertItem {
158	  produtoNome: string;
159	  quantidade: number;
160	  quantidadeMinima: number;
161	  /** true = zerado (vermelho); false = abaixo do mínimo (âmbar). */
162	  zerado: boolean;
163	}
164	
165	/** Heartbeat de movimentações de estoque de uma unidade no dia. */
166	export interface TvMovementSummary {
167	  /** Contagem de movimentações tipo `entrada` hoje. */
168	  entradas: number;
169	  /** Contagem de movimentações tipo `saida` hoje. */
170	  saidas: number;
171	  /** Timestamp ISO da última movimentação ("última bipagem"), ou null. */
172	  ultimaBipagem: string | null;
173	}
174	
175	/** Dados de um card de loja no grid. */
176	export interface TvStoreData {
177	  lojaId: number;
178	  nome: string;
179	  channel: TvSalesChannel;
180	  /** Vendas do dia de referência (null quando não há dado disponível). */
181	  vendas: TvSalesSnapshot | null;
182	  /** Meta do dia da semana de referência (`metas_vendas`), ou null. */
183	  metaDia: number | null;
184	  /**
185	   * % da meta. Canal live = pró-rata da janela de funcionamento;
186	   * canal defasado = % do dia COMPLETO de referência (dia já encerrado).
187	   * null quando não há meta cadastrada ou fora da janela.
188	   */
189	  pctMeta: number | null;
190	  /**
191	   * Delta % vs MESMO DIA da semana anterior — comparativo SECUNDÁRIO desde
192	   * a v3 (o principal é {@link deltaOntem}); a UI decide o que mostrar.
193	   */
194	  deltaSemana: number | null;
195	  /**
196	   * Delta % vs DIA ANTERIOR — comparativo PRINCIPAL (v3).
197	   * Canal live: hoje vs ontem com base PRÓ-RATEADA no mesmo ponto do dia.
198	   * Canal defasado: último dia vs dia anterior a ele (dias completos).
199	   */
200	  deltaOntem: number | null;
201	  estoque: TvStockAlertSummary;
202	  movimentacao: TvMovementSummary;
203	  /** Perdas da loja no PERÍODO do filtro global (+ delta vs anterior). */
204	  perdas: TvPerdasSummary;
205	  /** Marketing (ações `acoes_marketing`) da loja no PERÍODO (+ delta). */
206	  marketing: TvMarketingSummary;
207	  /**
208	   * Estoque crítico NOMEADO, ordenado por severidade (zerados primeiro,
209	   * depois abaixo do mínimo por % faltante). Lista completa — a coluna
210	   * exibe o top 5; o drill-down, tudo.
211	   */
212	  criticalItems: TvCriticalItem[];
213	  /** Mini-feed "AGORA": últimas movimentações de hoje (mais recente 1º). */
214	  recentMoves: TvRecentMove[];
215	  rag: TvRagStatus;
216	  /** Motivos legíveis (pt-BR) que levaram ao estado RAG. */
217	  ragReasons: string[];
218	}
219	
220	/** Produção agregada da fábrica num dia. */
221	export interface TvFactoryProduction {
222	  /** Dia a que a produção se refere (YYYY-MM-DD — último dia com registro). */
223	  dataReferencia: string;
224	  /** Quantidade de produtos distintos produzidos. */
225	  itens: number;
226	  /** Soma das quantidades produzidas. */
227	  totalUnidades: number;
228	}
229	
230	/** Dados do card diferenciado da fábrica. */
231	export interface TvFactoryData {
232	  lojaId: number;
233	  nome: string;
234	  /** Produção do dia (`daily_production` com loja_id NULL), ou null. */
235	  producao: TvFactoryProduction | null;
236	  /** Expedições = movimentações da fábrica hoje (saídas para lojas). */
237	  expedicoes: TvMovementSummary;
238	  estoque: TvStockAlertSummary;
239	  /** Perdas da fábrica no PERÍODO do filtro global (+ delta). */
240	  perdas: TvPerdasSummary;
241	  /** Marketing (ações `acoes_marketing` da fábrica) no PERÍODO (+ delta). */
242	  marketing: TvMarketingSummary;
243	  /** Estoque crítico nomeado da fábrica (mesma ordenação das lojas). */
244	  criticalItems: TvCriticalItem[];
245	  /** Mini-feed "AGORA" da fábrica (últimas movimentações de hoje). */
246	  recentMoves: TvRecentMove[];
247	  rag: TvRagStatus;
248	  ragReasons: string[];
249	}
250	
251	/** Uma linha da faixa de exceções. */
252	export interface TvException {
253	  /** Id estável para keys de render (ex.: `stock-out:4:BROWNIE`). */
254	  id: string;
255	  kind: TvExceptionKind;
256	  severity: TvExceptionSeverity;
257	  lojaId: number | null;
258	  lojaNome: string | null;
259	  /** Mensagem pronta para exibição (pt-BR). */
260	  message: string;
261	  produtoNome?: string;
262	  quantidade?: number;
263	  quantidadeMinima?: number;
264	}
265	
266	/** Faixa de exceções já ordenada (vermelho antes de âmbar) e limitada. */
267	export interface TvExceptionsResult {
268	  items: TvException[];
269	  /** Quantas exceções ficaram de fora do limite (para "+N itens"). */
270	  overflowCount: number;
271	  /** Total de exceções antes do corte. */
272	  totalCount: number;
273	}
274	
275	/** Resumo da rede para o hero. */
276	export interface TvNetworkSummary {
277	  /**
278	   * Vendas de HOJE em R$ — soma apenas das lojas cujo dado é de hoje
279	   * (canal live). Lojas defasadas NÃO entram para não misturar dias.
280	   */
281	  vendasHoje: number;
282	  /** Soma das metas do dia das lojas que contribuem em `vendasHoje`. */
283	  metaDia: number | null;
284	  /** % da meta pró-rata da rede (mesma regra do card de loja live). */
285	  pctMetaProRata: number | null;
286	  /**
287	   * Delta % vs mesmo dia da semana passada (lojas live) — SECUNDÁRIO
288	   * desde a v3 ({@link deltaOntem} é o principal), ou null.
289	   */
290	  deltaSemana: number | null;
291	  /**
292	   * Delta % vs ONTEM (lojas live, base pró-rateada no mesmo ponto do
293	   * dia) — comparativo PRINCIPAL da v3, ou null.
294	   */
295	  deltaOntem: number | null;
296	  /**
297	   * Perdas da REDE no período do filtro (toda a tabela `perdas`,
298	   * inclusive linhas sem loja_id — que não aparecem em nenhuma coluna).
299	   */
300	  perdas: TvPerdasSummary;
301	  /**
302	   * Marketing da REDE no período (ações `acoes_marketing` de todas as lojas).
303	   */
304	  marketing: TvMarketingSummary;
305	  /** Total de exceções vermelhas na rede (sem cap de exibição). */
306	  alertasCriticos: number;
307	  /** Ticket médio da rede (vendasHoje / totalCupons), ou null. */
308	  ticketMedio: number | null;
309	  /** R$ por hora decorrida na janela comercial (vendasHoje / horas desde abertura). */
310	  valorPorHora: number | null;
311	  /** Vendas (transações) por hora decorrida na janela comercial. */
312	  vendasPorHora: number | null;
313	  /** Total de cupons/transações da rede (soma das lojas live). */
314	  totalCupons: number;
315	  /** Quantidade de lojas com venda ao vivo. */
316	  lojasLive: number;
317	  /** Quantidade de lojas com dado defasado. */
318	  lojasDefasadas: number;
319	}
320	
321	/** Frescor de um dado-fonte. */
322	export interface TvSourceFreshness {
323	  /** Última atualização bem-sucedida (ISO), ou null se nunca carregou. */
324	  updatedAt: string | null;
325	  level: TvFreshnessLevel;
326	  /** Intervalo esperado de atualização (ms) usado na classificação. */
327	  expectedIntervalMs: number;
328	}
329	
330	/** Freshness consolidado dos dados exibidos na TV. */
331	export interface TvFreshness {
332	  /** Vendas live (polling 60s na edge `degust-pos-financial`). */
333	  vendasLive: TvSourceFreshness;
334	  /** Estoque/alertas (polling 5min + Realtime). */
335	  estoque: TvSourceFreshness;
336	  /** Momento em que o snapshot foi montado (ISO). */
337	  geradoEm: string;
338	}
