635	// Agregações determinísticas usadas pelo hook (puras, testáveis)
636	// ─────────────────────────────────────────────────────────────────────────────
637	
638	/** Linha mínima de `movimentacoes` necessária à agregação. */
639	export interface MovementRow {
640	  loja_id: number | null;
641	  tipo_movimentacao: string;
642	  data_movimentacao: string | null;
643	}
644	
645	/** Resultado por loja da agregação de movimentações do dia. */
646	export interface MovementAggregate {
647	  entradas: number;
648	  saidas: number;
649	  ultimaBipagem: string | null;
650	}
651	
652	/**
653	 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
654	 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
655	 * são ignoradas.
656	 */
657	export function aggregateMovements(
658	  rows: MovementRow[],
659	): Map<number, MovementAggregate> {
660	  const out = new Map<number, MovementAggregate>();
661	  for (const row of rows) {
662	    if (row.loja_id == null) continue;
663	    let agg = out.get(row.loja_id);
664	    if (!agg) {
665	      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
666	      out.set(row.loja_id, agg);
667	    }
668	    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
669	    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
670	    if (
671	      row.data_movimentacao &&
672	      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
673	    ) {
674	      agg.ultimaBipagem = row.data_movimentacao;
675	    }
676	  }
677	  return out;
678	}
