756	/**
757	 * Constrói as exceções de estoque (item × loja) a partir do detalhe por loja.
758	 * Itens zerados viram exceção vermelha; abaixo do mínimo, âmbar.
759	 */
760	export function buildStockExceptions(
761	  detailByLoja: Map<number, StockDetail>,
762	  lojaNomeById: Map<number, string>,
763	): TvException[] {
764	  const out: TvException[] = [];
765	  for (const [lojaId, detail] of detailByLoja) {
766	    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
767	    for (const item of detail.itens) {
768	      out.push({
769	        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
770	        kind: item.zerado ? 'stock-out' : 'stock-low',
771	        severity: item.zerado ? 'red' : 'amber',
772	        lojaId,
773	        lojaNome,
774	        message: item.zerado
775	          ? `${item.produtoNome} zerado — ${lojaNome}`
776	          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
777	        produtoNome: item.produtoNome,
778	        quantidade: item.quantidade,
779	        quantidadeMinima: item.quantidadeMinima,
780	      });
781	    }
782	  }
783	  return out;
784	}
