887	    total.itens += 1;
888	    if (row.loja_id == null) continue;
889	    let agg = byLoja.get(row.loja_id);
890	    if (!agg) {
891	      agg = { valor: 0, itens: 0 };
892	      byLoja.set(row.loja_id, agg);
893	    }
894	    agg.valor += valor;
895	    agg.itens += 1;
896	  }
897	  return { byLoja, total };
898	}
