536	async function loadPerdasRange(range: TvDateRange): Promise<PerdasByLoja> {
537	  const bounds = rangeToLocalDayBounds(range);
538	  // Paginado: um mês de perdas pode passar de 1000 linhas (corte silencioso
539	  // do PostgREST). `data_identificacao` é timestamptz → bounds de dia local.
540	  const rows = await fetchAllPages((from, to) =>
541	    supabase
542	      .from('perdas')
543	      .select('loja_id, valor_estimado')
544	      .gte('data_identificacao', bounds.startIso)
545	      .lt('data_identificacao', bounds.endExclusiveIso)
546	      .order('id')
547	      .range(from, to),
548	  );
549	  return aggregatePerdas(rows);
550	}
