696	/**
697	 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
698	 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
699	 * `freshness`). Vendas live re-buscam a cada 60s; o resto a
700	 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
701	 *
702	 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
703	 *   seus comparativos. Vendas dos cards são SEMPRE de hoje (+ % vs ontem).
704	 */
705	export function useTvDashboardData(period: TvPeriod = 'today'): TvDashboardData {
706	  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
707	  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
708	  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
709	  const tick = useMinuteClock();
710	
711	  const ctxQuery = useQuery({
712	    queryKey: tvDashboardKeys.context(),
713	    queryFn: fetchTvContext,
714	    staleTime: TV_QUERY_INTERVALS.slowMs,
715	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
716	  });
717	  const ctx = ctxQuery.data;
718	
719	  const liveQuery = useQuery({
720	    queryKey: tvDashboardKeys.liveSales(),
721	    queryFn: () => {
722	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
723	      return fetchLiveSales(ctx);
724	    },
725	    enabled: !!ctx,
726	    refetchInterval: TV_QUERY_INTERVALS.liveMs,
727	    staleTime: 30_000,
728	  });
729	
730	  const laggedQuery = useQuery({
731	    queryKey: tvDashboardKeys.laggedSales(),
732	    queryFn: () => {
733	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
734	      return fetchLaggedSales(ctx);
735	    },
736	    enabled: !!ctx,
737	    staleTime: TV_QUERY_INTERVALS.slowMs,
738	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
739	  });
740	
741	  const referenceQuery = useQuery({
742	    queryKey: tvDashboardKeys.referenceSales(),
743	    queryFn: () => {
744	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
745	      return fetchDegustReference(ctx);
746	    },
747	    enabled: !!ctx,
748	    staleTime: TV_QUERY_INTERVALS.slowMs,
749	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
