// Datas locais determinísticas (sem dependência de fuso/UTC)
const at = (hour: number, minute = 0) => new Date(2026, 5, 4, hour, minute, 0); // qui 04/06/2026

describe('datas locais', () => {
  it('toIsoDateLocal formata no fuso local', () => {
    expect(toIsoDateLocal(new Date(2026, 0, 9))).toBe('2026-01-09');
  });

  it('parseIsoDateLocal não sofre shift de fuso', () => {
    const d = parseIsoDateLocal('2026-04-09');
    expect(d.getFullYear()).toBe(2026);
    expect(d.getMonth()).toBe(3);
    expect(d.getDate()).toBe(9);
  });

  it('formatLaggedDateLabel gera "até DD/MM"', () => {
    expect(formatLaggedDateLabel('2026-04-09')).toBe('até 09/04');
  });
});

describe('businessDayFraction', () => {
  it('retorna 0 antes da janela (lojas abrem 10h — design §1.6)', () => {
    expect(businessDayFraction(at(8))).toBe(0);
    expect(businessDayFraction(at(TV_BUSINESS_HOURS.start))).toBe(0); // exatamente na abertura
  });

  it('retorna 1 depois da janela (lojas fecham 22h)', () => {
    expect(businessDayFraction(at(22))).toBe(1);
    expect(businessDayFraction(at(23, 30))).toBe(1);
  });

  it('interpola linearmente dentro da janela (10-22)', () => {
    expect(businessDayFraction(at(16))).toBeCloseTo(0.5, 5); // metade do dia
    expect(businessDayFraction(at(13))).toBeCloseTo(0.25, 5);
    expect(businessDayFraction(at(13, 30))).toBeCloseTo(3.5 / 12, 5);
  });

  it('janela da fábrica (06-18) interpola com a constante própria', () => {
    expect(businessDayFraction(at(12), TV_FACTORY_HOURS)).toBeCloseTo(0.5, 5);
    expect(businessDayFraction(at(5), TV_FACTORY_HOURS)).toBe(0);
    expect(businessDayFraction(at(18), TV_FACTORY_HOURS)).toBe(1);
  });

  it('aceita janela customizada', () => {
    expect(businessDayFraction(at(11), { start: 10, end: 12 })).toBeCloseTo(0.5, 5);
  });

  it('janela inválida (end <= start) não divide por zero', () => {
    expect(businessDayFraction(at(8), { start: 10, end: 10 })).toBe(0);
    expect(businessDayFraction(at(12), { start: 10, end: 10 })).toBe(1);
  });
});

