75	 * Comparar SEMPRE por igualdade exata pós-{@link normalizeSetor} (nunca por
76	 * prefixo/ILIKE: existe o setor "PRODUTOS DE LIMPEZA") — use
77	 * {@link isTvAlertSetor}.
78	 */
79	export const TV_ALERT_SETOR = 'PRODUTOS';
