81	// ─────────────────────────────────────────────────────────────────────────────
82	// Datas (helpers locais, sem dependência de timezone UTC)
83	// ─────────────────────────────────────────────────────────────────────────────
84	
85	/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
86	export function toIsoDateLocal(d: Date): string {
87	  const y = d.getFullYear();
88	  const m = String(d.getMonth() + 1).padStart(2, '0');
89	  const day = String(d.getDate()).padStart(2, '0');
90	  return `${y}-${m}-${day}`;
91	}
92	
93	/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
94	export function parseIsoDateLocal(iso: string): Date {
95	  const [y, m, d] = iso.split('-').map(Number);
96	  return new Date(y, (m ?? 1) - 1, d ?? 1);
97	}
98	
99	/** Soma `days` dias a uma data, retornando nova instância. */
100	export function addDays(d: Date, days: number): Date {
101	  const out = new Date(d);
102	  out.setDate(out.getDate() + days);
103	  return out;
104	}
105	
106	/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
107	export function formatLaggedDateLabel(isoDate: string): string {
108	  const d = parseIsoDateLocal(isoDate);
109	  const dd = String(d.getDate()).padStart(2, '0');
110	  const mm = String(d.getMonth() + 1).padStart(2, '0');
111	  return `até ${dd}/${mm}`;
112	}
113	
114	/**
115	 * Parser do timestamp pt-BR do Degust (`ultima_atualizacao` vem como
116	 * "DD/MM/YYYY HH:mm:ss"): `new Date()` interpreta como MM/DD e FALHA para
117	 * dia maior que 12. Faz parse como data LOCAL; aceita segundos opcionais e
118	 * cai pro parse nativo para outros formatos (ex.: ISO). Inválido → null.
119	 */
120	export function parseBrDateTime(value: string | null | undefined): Date | null {
121	  if (!value) return null;
122	  const m = value.match(
123	    /^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?$/,
124	  );
125	  if (m) {
126	    const [, dd, mm, yyyy, hh, mi, ss] = m;
127	    const month = Number(mm);
128	    const day = Number(dd);
129	    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
130	    return new Date(
131	      Number(yyyy),
132	      month - 1,
133	      day,
134	      Number(hh),
135	      Number(mi),
136	      ss ? Number(ss) : 0,
137	    );
138	  }
139	  const fallback = new Date(value);
140	  return Number.isNaN(fallback.getTime()) ? null : fallback;
141	}
142	
143	/** Hora local "HH:mm" de um timestamp ISO ("—" para ausente/inválido). */
144	export function timeHHMMFromIso(iso: string | null | undefined): string {
145	  if (!iso) return '—';
146	  const d = new Date(iso);
147	  if (Number.isNaN(d.getTime())) return '—';
148	  const hh = String(d.getHours()).padStart(2, '0');
149	  const mm = String(d.getMinutes()).padStart(2, '0');
150	  return `${hh}:${mm}`;
151	}
152	
153	// ─────────────────────────────────────────────────────────────────────────────
154	// Ranges do filtro global de período (v3) — datas LOCAIS, puras e testáveis
155	// ─────────────────────────────────────────────────────────────────────────────
156	
157	/**
158	 * Range do filtro global (fechado [from, to], YYYY-MM-DD local):
159	 * - `today`: hoje → hoje;
160	 * - `week`: segunda-feira da semana corrente → hoje;
161	 * - `month`: dia 1º do mês corrente → hoje.
162	 */
163	export function periodRange(period: TvPeriod, now: Date): TvDateRange {
164	  const today = toIsoDateLocal(now);
165	  if (period === 'today') return { from: today, to: today };
166	  if (period === 'week') {
167	    // getDay(): 0=domingo → 0=segunda com (dow+6)%7
168	    const dowFromMonday = (now.getDay() + 6) % 7;
169	    const monday = addDays(now, -dowFromMonday);
170	    return { from: toIsoDateLocal(monday), to: today };
171	  }
172	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
173	  return { from: toIsoDateLocal(firstOfMonth), to: today };
174	}
175	
176	/**
177	 * Período ANTERIOR equivalente para comparativos do filtro global:
178	 * - `today`: ontem → ontem;
179	 * - `week`: semana passada até o MESMO dia da semana (seg → hoje−7);
180	 * - `month`: mês passado do dia 1º até o MESMO dia do mês — clampado ao
181	 *   último dia quando o mês anterior é mais curto (31/05 → 30/04).
182	 */
183	export function previousPeriodRange(period: TvPeriod, now: Date): TvDateRange {
184	  if (period === 'today') {
185	    const yesterday = toIsoDateLocal(addDays(now, -1));
186	    return { from: yesterday, to: yesterday };
187	  }
188	  if (period === 'week') {
189	    const dowFromMonday = (now.getDay() + 6) % 7;
190	    const mondayLastWeek = addDays(now, -dowFromMonday - 7);
191	    return {
192	      from: toIsoDateLocal(mondayLastWeek),
193	      to: toIsoDateLocal(addDays(now, -7)),
194	    };
195	  }
196	  const y = now.getFullYear();
197	  const m = now.getMonth();
198	  const firstPrev = new Date(y, m - 1, 1);
199	  // `new Date(y, m, 0)` = último dia do mês ANTERIOR a `m`
200	  const lastDayPrevMonth = new Date(y, m, 0).getDate();
201	  const toPrev = new Date(y, m - 1, Math.min(now.getDate(), lastDayPrevMonth));
202	  return { from: toIsoDateLocal(firstPrev), to: toIsoDateLocal(toPrev) };
203	}
204	
205	/**
206	 * Range anterior de MESMA DURAÇÃO em dias, imediatamente antes do range
207	 * dado (drill-down com filtro custom: [from−N, from−1] para N dias).
208	 */
209	export function previousRangeSameDuration(range: TvDateRange): TvDateRange {
210	  const from = parseIsoDateLocal(range.from);
211	  const to = parseIsoDateLocal(range.to);
212	  // Math.round absorve a hora de DST (diferença 23h/25h em viradas de horário)
213	  const days = Math.round((to.getTime() - from.getTime()) / 86_400_000) + 1;
214	  return {
215	    from: toIsoDateLocal(addDays(from, -days)),
216	    to: toIsoDateLocal(addDays(to, -days)),
217	  };
218	}
219	
220	/**
221	 * Converte um range de DIAS locais em limites de TIMESTAMP para filtrar
222	 * colunas timestamptz (ex.: `perdas.data_identificacao`): início = 00:00
223	 * local do 1º dia (inclusive); fim = 00:00 local do dia SEGUINTE ao último
224	 * (exclusivo — usar `.lt`, nunca `.lte`).
225	 */
226	export function rangeToLocalDayBounds(range: TvDateRange): {
227	  startIso: string;
228	  endExclusiveIso: string;
229	} {
230	  const start = parseIsoDateLocal(range.from);
231	  const endExclusive = addDays(parseIsoDateLocal(range.to), 1);
232	  return {
233	    startIso: start.toISOString(),
234	    endExclusiveIso: endExclusive.toISOString(),
235	  };
236	}
