601	const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
602	// design.md §6.1: rupturas → abaixo-do-mínimo → sem-bipagem → stale
603	const KIND_ORDER: Record<string, number> = {
604	  'stock-out': 0,
605	  'stock-low': 1,
606	  'no-movement': 2,
607	  'stale-data': 3,
608	};
