610	/**
611	 * Ordena exceções por severidade (vermelho antes de âmbar), depois por tipo
612	 * (falta total, abaixo do mínimo, sem movimentação, dado stale — nesta ordem,
613	 * design.md §6.1) e por mensagem (estável), limitando a `limit` linhas com
614	 * contagem do excedente.
615	 */
616	export function sortAndLimitExceptions(
617	  exceptions: TvException[],
618	  limit: number = TV_EXCEPTIONS_LIMIT,
619	): TvExceptionsResult {
620	  const sorted = [...exceptions].sort((a, b) => {
621	    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
622	    if (sev !== 0) return sev;
623	    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
624	    if (kind !== 0) return kind;
625	    return a.message.localeCompare(b.message, 'pt-BR');
626	  });
627	  return {
628	    items: sorted.slice(0, limit),
629	    overflowCount: Math.max(0, sorted.length - limit),
630	    totalCount: sorted.length,
631	  };
632	}
