680	/**
681	 * Normaliza um valor de `produtos_master.setor` para comparação: trim,
682	 * minúsculas e remoção de acentos (NFD). O banco tem caixa/acentuação
683	 * inconsistentes no MESMO setor (ex.: "CÂMARA FRIA" e "Câmara Fria") —
684	 * toda comparação de setor DEVE passar por aqui.
685	 */
686	export function normalizeSetor(value: string | null | undefined): string {
687	  return (value ?? '')
688	    .normalize('NFD')
689	    .replace(/\p{M}/gu, '')
690	    .trim()
691	    .toLowerCase();
