719	/**
720	 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
721	 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
722	 * query). Regras (critério existente do projeto, sem schema novo):
723	 * - SÓ setor {@link TV_ALERT_SETOR} entra em alerta (regra do CTO
724	 *   2026-06-05: alertas só do setor de produtos vendáveis) — comparação
725	 *   normalizada client-side porque a caixa no banco é inconsistente;
726	 * - zerado (vermelho): quantidade ≤ 0 com mínimo definido (positivo);
727	 * - abaixo do mínimo (âmbar): quantidade entre 0 exclusivo e o mínimo.
728	 */
729	export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
730	  const out = new Map<number, StockDetail>();
731	  for (const row of rows) {
732	    if (row.loja_id == null) continue;
733	    if (!isTvAlertSetor(row.setor)) continue; // fora do setor vendável → sem alerta
734	    const min = row.quantidade_minima ?? 0;
735	    if (min <= 0) continue; // sem mínimo definido → sem alerta
736	    const qty = row.quantidade_atual ?? 0;
737	    if (qty >= min) continue; // dentro do normal
738	    let detail = out.get(row.loja_id);
739	    if (!detail) {
740	      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
741	      out.set(row.loja_id, detail);
742	    }
743	    const zerado = qty <= 0;
744	    if (zerado) detail.zerados += 1;
745	    else detail.abaixoMinimo += 1;
746	    detail.itens.push({
747	      produtoNome: row.produtoNome,
748	      quantidade: qty,
749	      quantidadeMinima: min,
750	      zerado,
751	    });
752	  }
753	  return out;
754	}
