988	
989	/** Página de resultado mínima consumida por {@link fetchAllPages}. */
990	export interface TvPageResult<T> {
991	  data: T[] | null;
992	  error: { message: string } | null;
993	}
994	
995	/**
996	 * Busca TODAS as linhas paginando com `.range()`: o PostgREST corta qualquer
997	 * resposta em 1000 linhas mesmo com `.limit()` maior — truncamento SILENCIOSO
998	 * (mesmo padrão de `features/producao/hooks/useProductionForecast`).
999	 *
1000	 * Loop até a página vir menor que `pageSize`. O fetcher é injetado (esta
1001	 * função não faz I/O próprio — testável com mock) e DEVE aplicar ordenação
1002	 * estável (`.order` em coluna única, ex.: `id`) para as páginas não se
1003	 * sobreporem entre requests.
1004	 */
1005	export async function fetchAllPages<T>(
1006	  fetchPage: (from: number, to: number) => PromiseLike<TvPageResult<T>>,
1007	  pageSize = 1000,
1008	): Promise<T[]> {
1009	  const all: T[] = [];
1010	  let offset = 0;
1011	  for (;;) {
1012	    const { data, error } = await fetchPage(offset, offset + pageSize - 1);
1013	    if (error) throw error;
1014	    const rows = data ?? [];
1015	    all.push(...rows);
1016	    if (rows.length < pageSize) return all;
1017	    offset += pageSize;
1018	  }
1019	}
