273	// ─────────────────────────────────────────────────────────────────────────────
274	// Vendas defasadas (Linx via historico_vendas — último dia disponível)
275	// ─────────────────────────────────────────────────────────────────────────────
276	
277	interface LaggedSales {
278	  lojaId: number;
279	  /** Último dia com venda registrada (YYYY-MM-DD). */
280	  dataReferencia: string;
281	  valor: number;
282	  quantidade: number;
283	  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
284	  valorSemanaAnterior: number | null;
285	  /** Valor do DIA ANTERIOR ao dia de referência (dias completos), ou null. */
286	  valorDiaAnterior: number | null;
287	}
288	
289	async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
290	  // 1) Último dia com dado para a loja
291	  const { data: latest, error: latestErr } = await supabase
292	    .from('historico_vendas')
293	    .select('data')
294	    .eq('loja_id', lojaId)
295	    .order('data', { ascending: false })
296	    .limit(1);
297	  if (latestErr) throw latestErr;
298	  const refDate = latest?.[0]?.data;
299	  if (!refDate) return null;
300	
301	  const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
302	  const dayBeforeDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -1));
303	
304	  // 2) Vendas do dia de referência + bases de comparação (dia anterior =
305	  //    comparativo PRINCIPAL v3; mesma semana = secundário)
306	  const [curRes, weekRes, dayRes] = await Promise.all([
307	    supabase
308	      .from('historico_vendas')
309	      .select('valor_total, quantidade')
310	      .eq('loja_id', lojaId)
311	      .eq('data', refDate)
312	      .limit(2000),
313	    supabase
314	      .from('historico_vendas')
315	      .select('valor_total')
316	      .eq('loja_id', lojaId)
317	      .eq('data', weekAgoDate)
318	      .limit(2000),
319	    supabase
320	      .from('historico_vendas')
321	      .select('valor_total')
322	      .eq('loja_id', lojaId)
323	      .eq('data', dayBeforeDate)
324	      .limit(2000),
325	  ]);
326	  if (curRes.error) throw curRes.error;
327	  if (weekRes.error) throw weekRes.error;
328	  if (dayRes.error) throw dayRes.error;
329	
330	  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
331	  const quantidade = (curRes.data ?? []).reduce(
332	    (s, r) => s + (r.quantidade ?? 0),
333	    0,
334	  );
335	  const sumOrNull = (rows: Array<{ valor_total: number | null }> | null) => {
336	    const list = rows ?? [];
337	    return list.length > 0
338	      ? list.reduce((s, r) => s + (r.valor_total ?? 0), 0)
339	      : null;
340	  };
341	
342	  return {
343	    lojaId,
344	    dataReferencia: refDate,
345	    valor,
346	    quantidade,
347	    valorSemanaAnterior: sumOrNull(weekRes.data),
348	    valorDiaAnterior: sumOrNull(dayRes.data),
349	  };
350	}
351	
352	async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
353	  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
354	  return results.filter((r): r is LaggedSales => r !== null);
355	}
