357	// ─────────────────────────────────────────────────────────────────────────────
358	// Bases de comparação Degust: ONTEM (principal v3) + mesmo dia da semana
359	// passada (secundário) — uma única query em degust_vendas_diarias
360	// ─────────────────────────────────────────────────────────────────────────────
361	
362	interface DegustReferenceSales {
363	  /** R$ por loja ONTEM (base do delta principal, pró-rateada no uso). */
364	  yesterday: Map<number, number>;
365	  /** R$ por loja no MESMO DIA da semana passada (delta secundário). */
366	  lastWeek: Map<number, number>;
367	}
368	
369	async function fetchDegustReference(ctx: TvContext): Promise<DegustReferenceSales> {
370	  const yesterday = new Map<number, number>();
371	  const lastWeek = new Map<number, number>();
372	  const ids = [...ctx.degustLojaIds];
373	  if (ids.length === 0) return { yesterday, lastWeek };
374	  const now = new Date();
375	  const yesterdayDate = toIsoDateLocal(addDays(now, -1));
376	  const lastWeekDate = toIsoDateLocal(addDays(now, -7));
377	  // Paginado: degust_vendas_diarias é linha-por-produto (2 dias × N lojas
378	  // pode passar de 1000 — o PostgREST cortaria silenciosamente).
379	  const rows = await fetchAllPages((from, to) =>
380	    supabase
381	      .from('degust_vendas_diarias')
382	      .select('loja_id, valor_total, data')
383	      .in('data', [yesterdayDate, lastWeekDate])
384	      .in('loja_id', ids)
385	      .order('id')
386	      .range(from, to),
387	  );
388	  for (const row of rows) {
389	    const target = row.data === yesterdayDate ? yesterday : lastWeek;
390	    target.set(row.loja_id, (target.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
391	  }
392	  return { yesterday, lastWeek };
393	}
