399	async function fetchMetas(): Promise<Map<string, number>> {
400	  const { data, error } = await supabase
401	    .from('metas_vendas')
402	    .select('loja_id, dia_semana, valor_meta')
403	    .limit(1000);
404	  if (error) throw error;
405	  const out = new Map<string, number>();
406	  for (const row of data ?? []) {
407	    out.set(`${row.loja_id}:${row.dia_semana}`, row.valor_meta);
408	  }
409	  return out;
410	}
