412	function metaFor(
413	  metas: Map<string, number> | undefined,
414	  lojaId: number,
415	  date: Date,
416	): number | null {
417	  if (!metas) return null;
418	  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
419	}
