592	// ─────────────────────────────────────────────────────────────────────────────
593	// Produção da fábrica (daily_production com loja_id NULL = fábrica)
594	// ─────────────────────────────────────────────────────────────────────────────
595	
596	async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
597	  const today = toIsoDateLocal(new Date());
598	
599	  const loadDay = async (date: string) => {
600	    const { data, error } = await supabase
601	      .from('daily_production')
602	      .select('quantity')
603	      .is('loja_id', null)
604	      .eq('date', date)
605	      .limit(2000);
606	    if (error) throw error;
607	    return data ?? [];
608	  };
609	
610	  let refDate = today;
611	  let rows = await loadDay(today);
612	  if (rows.length === 0) {
613	    // Sem produção registrada hoje → mostra o último dia disponível
614	    const { data: latest, error } = await supabase
615	      .from('daily_production')
616	      .select('date')
617	      .is('loja_id', null)
618	      .lte('date', today)
619	      .order('date', { ascending: false })
620	      .limit(1);
621	    if (error) throw error;
622	    const lastDate = latest?.[0]?.date;
623	    if (!lastDate) return null;
624	    refDate = lastDate;
625	    rows = await loadDay(lastDate);
626	  }
627	
628	  return {
629	    dataReferencia: refDate,
630	    itens: rows.length,
631	    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
632	  };
633	}
