696	/**
697	 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
698	 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
699	 * `freshness`). Vendas live re-buscam a cada 60s; o resto a
700	 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
701	 *
702	 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
703	 *   seus comparativos. Vendas dos cards são SEMPRE de hoje (+ % vs ontem).
704	 */
705	export function useTvDashboardData(period: TvPeriod = 'today'): TvDashboardData {
706	  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
707	  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
708	  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
709	  const tick = useMinuteClock();
710	
711	  const ctxQuery = useQuery({
712	    queryKey: tvDashboardKeys.context(),
713	    queryFn: fetchTvContext,
714	    staleTime: TV_QUERY_INTERVALS.slowMs,
715	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
716	  });
717	  const ctx = ctxQuery.data;
718	
719	  const liveQuery = useQuery({
720	    queryKey: tvDashboardKeys.liveSales(),
721	    queryFn: () => {
722	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
723	      return fetchLiveSales(ctx);
724	    },
725	    enabled: !!ctx,
726	    refetchInterval: TV_QUERY_INTERVALS.liveMs,
727	    staleTime: 30_000,
728	  });
729	
730	  const laggedQuery = useQuery({
731	    queryKey: tvDashboardKeys.laggedSales(),
732	    queryFn: () => {
733	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
734	      return fetchLaggedSales(ctx);
735	    },
736	    enabled: !!ctx,
737	    staleTime: TV_QUERY_INTERVALS.slowMs,
738	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
739	  });
740	
741	  const referenceQuery = useQuery({
742	    queryKey: tvDashboardKeys.referenceSales(),
743	    queryFn: () => {
744	      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
745	      return fetchDegustReference(ctx);
746	    },
747	    enabled: !!ctx,
748	    staleTime: TV_QUERY_INTERVALS.slowMs,
749	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
750	  });
751	
752	  const perdasQuery = useQuery({
753	    queryKey: tvDashboardKeys.perdas(period),
754	    queryFn: () => fetchPerdasAggregates(period),
755	    staleTime: TV_QUERY_INTERVALS.slowMs,
756	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
757	  });
758	
759	  const marketingQuery = useQuery({
760	    queryKey: tvDashboardKeys.marketing(period),
761	    queryFn: () => fetchMarketingAggregates(period),
762	    staleTime: TV_QUERY_INTERVALS.slowMs,
763	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
764	  });
765	
766	  const feedQuery = useQuery({
767	    queryKey: tvDashboardKeys.movementFeed(),
768	    queryFn: fetchMovementFeed,
769	    staleTime: TV_QUERY_INTERVALS.slowMs,
770	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
771	  });
772	
773	  const metasQuery = useQuery({
774	    queryKey: tvDashboardKeys.metas(),
775	    queryFn: fetchMetas,
776	    staleTime: TV_QUERY_INTERVALS.slowMs,
777	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
778	  });
779	
780	  const stockQuery = useQuery({
781	    queryKey: tvDashboardKeys.stock(),
782	    queryFn: fetchStockAlerts,
783	    staleTime: TV_QUERY_INTERVALS.slowMs,
784	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
785	  });
786	
787	  const movementsQuery = useQuery({
788	    queryKey: tvDashboardKeys.movements(),
789	    queryFn: fetchMovementsToday,
790	    staleTime: TV_QUERY_INTERVALS.slowMs,
791	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
792	  });
793	
794	  const factoryQuery = useQuery({
795	    queryKey: tvDashboardKeys.factoryProduction(),
796	    queryFn: fetchFactoryProduction,
797	    staleTime: TV_QUERY_INTERVALS.slowMs,
798	    refetchInterval: TV_QUERY_INTERVALS.slowMs,
799	  });
800	
801	  return useMemo<TvDashboardData>(() => {
802	    const now = tick;
803	    const todayIso = toIsoDateLocal(now);
804	    const range = periodRange(period, now);
805	    const previousRange = previousPeriodRange(period, now);
806	
807	    const stockDetail: Map<number, StockDetail> = buildStockSummary(
808	      stockQuery.data ?? [],
809	    );
810	    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
811	    const feedByLoja = feedQuery.data ?? new Map<number, TvRecentMove[]>();
812	    const flashByLoja = new Map<number, FlashRow>(
813	      (liveQuery.data?.flash ?? []).map((f) => [f.loja_id, f]),
814	    );
815	    // dailyByLoja: loja → data → total (3 dias, do ticket-medio API)
816	    const dailyByLoja: Map<number, Map<string, number>> =
817	      liveQuery.data?.dailyByLoja ?? new Map<number, Map<string, number>>();
818	    const laggedByLoja = new Map<number, LaggedSales>(
819	      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
820	    );
821	    const lastWeekByLoja = referenceQuery.data?.lastWeek ?? new Map<number, number>();
822	    // yesterdayByLoja do degust_vendas_diarias — pode ter sync parcial;
823	    // preferir yesterdayFromApiByLoja quando disponível
824	    const yesterdayByLoja = referenceQuery.data?.yesterday ?? new Map<number, number>();
825	    const perdasAgg = perdasQuery.data;
826	    const marketingAgg = marketingQuery.data;
827	    const lojaNomeById = new Map<number, string>(
828	      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
829	    );
830	
831	    // ── Cards de loja ──
832	    const stores: TvStoreData[] = (ctx?.lojas ?? [])
833	      .filter((l) => !isFactoryTipo(l.tipo))
834	      .map((loja) => {
835	        const channel: TvSalesChannel = ctx?.degustLojaIds.has(loja.id)
836	          ? 'degust-live'
837	          : 'linx-lagged';
838	        const stock = stockDetail.get(loja.id);
839	        const movement = movements.get(loja.id) ?? EMPTY_MOVEMENT;
840	
841	        let vendas: TvSalesSnapshot | null = null;
842	        let metaDia: number | null = null;
843	        let pctMeta: number | null = null;
844	        let deltaSemana: number | null = null;
845	        let deltaOntem: number | null = null;
846	
847	        if (channel === 'degust-live') {
848	          const flash = flashByLoja.get(loja.id);
849	          if (flash) {
850	            // dataReferencia = data real do flash (pode ser ontem à madrugada)
851	            const flashTimeRef = parseBrDateTime(flash.ultima_atualizacao);
852	            const flashDateRef = flashTimeRef ? toIsoDateLocal(flashTimeRef) : todayIso;
853	            vendas = {
854	              valor: flash.total_vendas,
855	              cupons: flash.total_cupons,
856	              ticketMedio: flash.ticket_medio,
857	              dataReferencia: flashDateRef,
858	              isLive: flash.caixa_aberto,  // só "ao vivo" se caixa estiver aberto
859	              caixaAberto: flash.caixa_aberto,
860	              atualizadoEm: flash.ultima_atualizacao,
861	            };
862	            metaDia = metaFor(metasQuery.data, loja.id, now);
863	            pctMeta = pctOfProRataTarget(flash.total_vendas, metaDia, now);
864	            // Detectar data real do flash via ultima_atualizacao.
865	            // Às 2AM o flash mostra o fechamento de ontem (ex: Jun 10),
866	            // mas today = Jun 11. Comparar Jun 10 vs "yesterday=Jun 10"
867	            // seria comparar o dia com ele mesmo → ~0%.
868	            // Correto: comparar o flash vs o DIA ANTERIOR à data do flash.
869	            const flashTime = parseBrDateTime(flash.ultima_atualizacao);
870	            const flashDate = flashTime ? toIsoDateLocal(flashTime) : todayIso;
871	            const prevDate = toIsoDateLocal(addDays(parseIsoDateLocal(flashDate), -1));
872	
873	            // Total do dia anterior ao flash (ticket-medio API, completo)
874	            // Fallback: degust_vendas_diarias (pode ter sync parcial)
875	            const prevDayTotal =
876	              dailyByLoja.get(loja.id)?.get(prevDate) ??
877	              yesterdayByLoja.get(loja.id) ??
878	              null;
879	            deltaOntem = relativeDelta(flash.total_vendas, prevDayTotal);
880	
881	            // deltaSemana: só quando period='week'
882	            if (period === 'week') {
883	              const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(flashDate), -7));
884	              const weekAgoTotal =
885	                dailyByLoja.get(loja.id)?.get(weekAgoDate) ??
886	                lastWeekByLoja.get(loja.id) ??
887	                null;
888	              deltaSemana = weekOverWeekDelta(
889	                flash.total_vendas,
890	                proRataDayBase(weekAgoTotal, now) ?? weekAgoTotal,
891	              );
892	            }
893	          }
894	        } else {
895	          const lagged = laggedByLoja.get(loja.id);
896	          if (lagged) {
897	            vendas = {
898	              valor: lagged.valor,
899	              cupons: null,
900	              ticketMedio: null,
901	              dataReferencia: lagged.dataReferencia,
902	              isLive: false,
903	              caixaAberto: null,
904	              atualizadoEm: null,
905	            };
906	            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
907	            const refDate = parseIsoDateLocal(lagged.dataReferencia);
908	            metaDia = metaFor(metasQuery.data, loja.id, refDate);
909	            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
910	            // Canal defasado: dia COMPLETO vs dia COMPLETO — sem pró-rata.
911	            // Principal v3 = vs dia ANTERIOR ao de referência.
912	            deltaOntem = relativeDelta(lagged.valor, lagged.valorDiaAnterior);
913	            deltaSemana = weekOverWeekDelta(
914	              lagged.valor,
915	              lagged.valorSemanaAnterior,
916	            );
917	          }
918	        }
919	
920	        const rag = classifyStoreRag({
921	          stockOutCount: stock?.zerados ?? 0,
922	          stockLowCount: stock?.abaixoMinimo ?? 0,
923	          pctMetaProRata: channel === 'degust-live' ? pctMeta : null,
924	          isLiveChannel: channel === 'degust-live',
925	          lastMovementAt: movement.ultimaBipagem,
926	          now,
927	        });
928	
929	        return {
930	          lojaId: loja.id,
931	          nome: loja.nome,
932	          channel,
933	          vendas,
934	          metaDia,
935	          pctMeta,
936	          deltaSemana,
937	          deltaOntem,
938	          estoque: {
939	            zerados: stock?.zerados ?? 0,
940	            abaixoMinimo: stock?.abaixoMinimo ?? 0,
941	          },
942	          movimentacao: movement,
943	          perdas: perdasSummaryFor(perdasAgg, loja.id),
944	          marketing: marketingSummaryFor(marketingAgg, loja.id),
945	          criticalItems: sortCriticalItems(stock?.itens ?? []),
946	          recentMoves: feedByLoja.get(loja.id) ?? [],
947	          rag: rag.status,
948	          ragReasons: rag.reasons,
949	        };
950	      });
951	
952	    // ── Card da fábrica ──
953	    let factory: TvFactoryData | null = null;
954	    if (ctx?.factoryLojaId != null) {
955	      const fid = ctx.factoryLojaId;
956	      const stock = stockDetail.get(fid);
957	      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
958	      const rag = classifyStoreRag({
959	        stockOutCount: stock?.zerados ?? 0,
960	        stockLowCount: stock?.abaixoMinimo ?? 0,
961	        pctMetaProRata: null,
962	        isLiveChannel: false,
963	        lastMovementAt: movement.ultimaBipagem,
964	        now,
965	        // Janela de PRODUÇÃO (06–18h, threshold 2h) — mesma do card visual
966	        hours: TV_FACTORY_HOURS,
967	        noMovementThresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
968	      });
969	      factory = {
970	        lojaId: fid,
971	        nome: lojaNomeById.get(fid) ?? 'Fábrica',
972	        producao: factoryQuery.data ?? null,
973	        expedicoes: movement,
974	        estoque: {
975	          zerados: stock?.zerados ?? 0,
976	          abaixoMinimo: stock?.abaixoMinimo ?? 0,
977	        },
978	        perdas: perdasSummaryFor(perdasAgg, fid),
979	        marketing: marketingSummaryFor(marketingAgg, fid),
980	        criticalItems: sortCriticalItems(stock?.itens ?? []),
981	        recentMoves: feedByLoja.get(fid) ?? [],
982	        rag: rag.status,
983	        ragReasons: rag.reasons,
984	      };
985	    }
986	
987	    // ── Freshness ──
988	    // Classificada com `now` do tick de minuto: quando dataUpdatedAt para de
989	    // avançar (outage), a idade cresce e o chip escala pra âmbar mesmo sem
990	    // nenhum dado novo chegar. Os timestamps CRUS ficam expostos no retorno.
991	    const freshness: TvFreshness = buildFreshness(
992	      liveQuery.dataUpdatedAt,
993	      stockQuery.dataUpdatedAt,
994	      TV_QUERY_INTERVALS,
995	      now,
996	    );
997	
998	    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
999	    const allExceptions: TvException[] = buildStockExceptions(
1000	      stockDetail,
1001	      lojaNomeById,
1002	    );
1003	    // "Sem movimentação" derivada do DADO estruturado (última bipagem ×
1004	    // janela), nunca por parsing de ragReasons — independe da cor do card
1005	    // (aparece mesmo com card vermelho) e cobre também a fábrica.
1006	    for (const store of stores) {
1007	      const noMovement = buildNoMovementException({
1008	        lojaId: store.lojaId,
1009	        lojaNome: store.nome,
1010	        lastMovementAt: store.movimentacao.ultimaBipagem,
1011	        now,
1012	      });
1013	      if (noMovement) allExceptions.push(noMovement);
1014	    }
1015	    if (factory) {
1016	      const noMovement = buildNoMovementException({
1017	        lojaId: factory.lojaId,
1018	        lojaNome: factory.nome,
1019	        lastMovementAt: factory.expedicoes.ultimaBipagem,
1020	        now,
1021	        hours: TV_FACTORY_HOURS,
1022	        thresholdHours: FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
1023	      });
1024	      if (noMovement) allExceptions.push(noMovement);
1025	    }
1026	    if (freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
1027	      const liveUpdatedAt = freshness.vendasLive.updatedAt;
1028	      allExceptions.push({
1029	        id: 'stale-data:vendas-live',
1030	        kind: 'stale-data',
1031	        severity: 'amber',
1032	        lojaId: null,
1033	        lojaNome: null,
1034	        message: liveUpdatedAt
1035	          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
1036	          : 'Venda live ainda não carregou',
1037	      });
1038	    }
1039	    const exceptions = sortAndLimitExceptions(allExceptions);
1040	
1041	    // ── Hero (rede) ──
1042	    // Inclui todas as lojas com canal degust-live que têm dado (caixa aberto
1043	    // ou fechado recentemente — a madrugada mostra o fechamento de ontem).
1044	    const liveStores = stores.filter((s) => s.channel === 'degust-live' && s.vendas != null);
1045	    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
1046	    const totalCupons = liveStores.reduce((s, st) => s + (st.vendas?.cupons ?? 0), 0);
1047	    const ticketMedioRede = totalCupons > 0 ? vendasHoje / totalCupons : null;
1048	    // R$/hora: vendasHoje dividido pelas horas decorridas na janela comercial
1049	    const businessFraction = businessDayFraction(now);
1050	    const horasDecorridas = businessFraction * 12; // janela 10h–22h = 12h
1051	    const valorPorHora = businessFraction > 0 && vendasHoje > 0
1052	      ? vendasHoje / horasDecorridas
1053	      : null;
1054	    const vendasPorHora = businessFraction > 0 && totalCupons > 0
1055	      ? totalCupons / horasDecorridas
1056	      : null;
1057	    const metasHoje = liveStores
1058	      .map((s) => s.metaDia)
1059	      .filter((m): m is number => m != null && m > 0);
1060	    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
