1063	    // o mesmo prevDate calculado por loja (já está em deltaOntem do store).
1064	    // Aqui recalculamos de forma agregada usando dailyByLoja.
1065	    const prevDayNetworkTotal = liveStores.reduce((sum, st) => {
1066	      const flash = flashByLoja.get(st.lojaId);
1067	      if (!flash) return sum;
1068	      const ft = parseBrDateTime(flash.ultima_atualizacao);
1069	      const fd = ft ? toIsoDateLocal(ft) : todayIso;
1070	      const pd = toIsoDateLocal(addDays(parseIsoDateLocal(fd), -1));
1071	      const prevVal = dailyByLoja.get(st.lojaId)?.get(pd) ?? yesterdayByLoja.get(st.lojaId) ?? 0;
1072	      return sum + prevVal;
1073	    }, 0);
1074	
1075	    const lastWeekTotal = liveStores.reduce((s, st) => {
1076	      const flash = flashByLoja.get(st.lojaId);
1077	      if (!flash) return s;
1078	      const ft = parseBrDateTime(flash.ultima_atualizacao);
1079	      const fd = ft ? toIsoDateLocal(ft) : todayIso;
1080	      const wd = toIsoDateLocal(addDays(parseIsoDateLocal(fd), -7));
1081	      return s + (dailyByLoja.get(st.lojaId)?.get(wd) ?? lastWeekByLoja.get(st.lojaId) ?? 0);
1082	    }, 0);
1083	    const network: TvNetworkSummary | null = ctx
1084	      ? {
1085	          vendasHoje,
1086	          ticketMedio: ticketMedioRede,
1087	          valorPorHora,
1088	          vendasPorHora,
1089	          totalCupons,
1090	          metaDia,
1091	          pctMetaProRata: pctOfProRataTarget(vendasHoje, metaDia, now),
1092	          // deltaSemana: só quando period='week'
1093	          deltaSemana: period === 'week'
1094	            ? weekOverWeekDelta(
1095	                vendasHoje,
1096	                proRataDayBase(lastWeekTotal, now) ?? (lastWeekTotal || null),
1097	              )
1098	            : null,
1099	          // deltaOntem: comparar vs dia anterior ao flash (robusto na virada de dia)
1100	          deltaOntem: relativeDelta(vendasHoje, prevDayNetworkTotal || null),
1101	          // Totais da REDE: incluem linhas sem loja_id (não atribuíveis a
1102	          // nenhuma coluna — entram SOMENTE aqui).
1103	          perdas: {
1104	            valor: perdasAgg?.current.total.valor ?? 0,
1105	            itens: perdasAgg?.current.total.itens ?? 0,
1106	            deltaPct: relativeDelta(
1107	              perdasAgg?.current.total.valor ?? 0,
1108	              perdasAgg?.previous.total.valor ?? null,
1109	            ),
1110	          },
1111	          marketing: {
1112	            valor: marketingAgg?.current.total.valor ?? 0,
1113	            acoes: marketingAgg?.current.total.acoes ?? 0,
1114	            deltaPct: relativeDelta(
1115	              marketingAgg?.current.total.valor ?? 0,
1116	              marketingAgg?.previous.total.valor ?? null,
1117	            ),
1118	          },
1119	          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
1120	          lojasLive: liveStores.length,
1121	          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
1122	        }
1123	      : null;
1124	
1125	    return {
