/** Cupom do POST /api/venda/relatorio-vendas (campos usados aqui). */
interface RelatorioVendasCupom {
  /** '1' = BALCÃO, '2' = DELIVERY (catálogo em /api/financeiro/tipos-venda). */
  tipoVenda: string
  /** Valor líquido do cupom como string ("86.00"). */
  valLiquido: string
  /** 'S' quando o cupom foi cancelado. */
  cancelada: string
  /** Data da venda "DD/MM/YYYY" (pode vir com hora — normalizamos). */
  dataVenda: string
}

/** Linha de resposta do modo includeDeliverySplit. */
interface DeliverySplitRow {
  data: string
  loja_id: number
  total_delivery: number
  cupons_delivery: number
}

/** Linha de resposta do modo includeHourly. */
interface HourlyRow {
  loja_id: number
  data: string
  byHour: Record<string, number>
}

/** "DD/MM/YYYY[ hh:mm:ss]" → "YYYY-MM-DD" (null se formato inesperado). */
function brDateToIso(value: string | undefined): string | null {
  const datePart = (value ?? '').split(' ')[0]
  const m = datePart.match(/^(\d{2})\/(\d{2})\/(\d{4})$/)
  if (!m) return null
  return `${m[3]}-${m[2]}-${m[1]}`
}

