    )
    if (!rvResp.ok) {
      throw new Error(`relatorio-vendas HTTP ${rvResp.status}`)
    }
    const cupons: RelatorioVendasCupom[] = await rvResp.json()
    const byDate: Record<string, { total: number; count: number }> = {}
    for (const cupom of Array.isArray(cupons) ? cupons : []) {
      if (cupom.tipoVenda !== '2' || cupom.cancelada === 'S') continue
      const iso = brDateToIso(cupom.dataVenda)
      if (!iso) continue
      const val = parseFloat(cupom.valLiquido)
      if (!Number.isFinite(val)) continue
      const agg = byDate[iso] ?? (byDate[iso] = { total: 0, count: 0 })
      agg.total += val
      agg.count += 1
    }
    deliverySplit = Object.entries(byDate)
      .map(([data, agg]) => ({
        data,
        loja_id: deliveryLojaId,
        total_delivery: Math.round(agg.total * 100) / 100,
        cupons_delivery: agg.count,
      }))
      .sort((a, b) => a.data.localeCompare(b.data))
