            const resp = await degustFetch(
              `${API}/api/financeiro/movimentacao-produtos?CodigoFranquia=${FRANQUIA}&CodigoLoja=${store.degust_loja_codigo}&DataCaixa=${dateStr}&api-version=1.0`,
