                resp.status,
              )
              return null
            }
            const rows: DegustTransaction[] = await resp.json()
            if (!Array.isArray(rows) || rows.length === 0) return null
            const byHour: Record<string, number> = {}
            for (const tx of rows) {
              // "10:31:12" → "10"; descarta hora malformada
              const hh = String(tx.hora ?? '').slice(0, 2)
              if (!/^\d{2}$/.test(hh)) continue
              byHour[hh] =
                (byHour[hh] ?? 0) + (tx.quantidade ?? 0) * (tx.valorUnitario ?? 0)
            }
            return { loja_id: store.loja_id, data: dateStr, byHour }
          } catch (e) {
            console.error(
              `[degust-pos] hourly loja ${store.degust_loja_codigo} ${dateStr} error:`,
              e,
            )
            return null
          }
        })(),
      )
    }
  }
  hourly = (await Promise.all(jobs)).filter((h): h is HourlyRow => h !== null)
}

