/**
 * Range do filtro global DESLOCADO `offset` períodos no tempo (R2 —
 * histórico navegável). Offset 0 = comportamento de {@link periodRange}
 * (período corrente, parcial até hoje). Offset −n = período PASSADO
 * COMPLETO n posições atrás:
 * - `today`: o dia inteiro n dias atrás;
 * - `week`: a semana seg-dom COMPLETA n semanas atrás;
 * - `month`: o mês-calendário COMPLETO n meses atrás.
 *
 * Offset positivo não é suportado (não há futuro a navegar) — tratado
 * como 0 por segurança.
 */
export function shiftedPeriodRange(
  period: TvPeriod,
  offset: number,
  now: Date,
): TvDateRange {
  if (offset >= 0) return periodRange(period, now);
  if (period === 'today') {
    const day = toIsoDateLocal(addDays(now, offset));
    return { from: day, to: day };
  }
  if (period === 'week') {
    const dowFromMonday = (now.getDay() + 6) % 7;
    const monday = addDays(now, -dowFromMonday + offset * 7);
    return { from: toIsoDateLocal(monday), to: toIsoDateLocal(addDays(monday, 6)) };
  }
  const first = new Date(now.getFullYear(), now.getMonth() + offset, 1);
  // `new Date(y, m+1, 0)` = último dia do mês `m`
  const last = new Date(now.getFullYear(), now.getMonth() + offset + 1, 0);
  return { from: toIsoDateLocal(first), to: toIsoDateLocal(last) };
}

// ─────────────────────────────────────────────────────────────────────────────
// Meta mensal — semanas seg-dom recortadas ao mês + redistribuição (R4)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Segmentos seg-dom de um mês, RECORTADOS aos limites do mês: o primeiro
 * e o último podem ter menos de 7 dias (mês que começa/termina no meio da
 * semana). `index` é 1-based ("Semana 1").
 *
 * @param year - Ano (ex.: 2026).
 * @param monthIndex0 - Mês 0-based (convenção JS `Date.getMonth()`).
 */
export function monthWeekSegments(
  year: number,
  monthIndex0: number,
): TvWeekSegment[] {
  const lastDay = new Date(year, monthIndex0 + 1, 0).getDate();
  const segments: TvWeekSegment[] = [];
  let day = 1;
  let index = 1;
  while (day <= lastDay) {
    const start = new Date(year, monthIndex0, day);
    const dowFromMonday = (start.getDay() + 6) % 7;
    const endDay = Math.min(day + (6 - dowFromMonday), lastDay);
    segments.push({
      index,
      from: toIsoDateLocal(start),
      to: toIsoDateLocal(new Date(year, monthIndex0, endDay)),
      days: endDay - day + 1,
    });
    day = endDay + 1;
    index += 1;
  }
  return segments;
}

/**
 * Metas semanais do mês de `now` com REDISTRIBUIÇÃO iterativa da meta
 * mensal (que é fixa): para cada segmento, em ordem,
 * `target = (metaMensal − comprometido) × dias do segmento ÷ dias restantes`,
 * onde "comprometido" acumula o REALIZADO das semanas já encerradas e o
 * TARGET das semanas correntes/futuras (assume on-target dali em diante).
 *
 * Consequências (A4 da spec):
 * - semana que não bate a meta ⇒ targets das seguintes SOBEM;
 * - semana que supera ⇒ targets das seguintes DESCEM;
 * - invariante: realizado das semanas passadas + soma dos targets
 *   restantes = metaMensal, sempre (targets podem ficar negativos se o
 *   realizado já passou da meta — honesto, sem clamp).
 *
 * `achieved` = soma de `realizadoPorDia` nos dias do segmento (semanas
 * passadas e corrente); null para semanas futuras (sem dados ainda).
 */
export function weeklyTargets(
  metaMensal: number,
  realizadoPorDia: Map<string, number>,
  now: Date,
): TvWeeklyGoal[] {
  const segments = monthWeekSegments(now.getFullYear(), now.getMonth());
  const todayIso = toIsoDateLocal(now);
  const sumSegment = (seg: TvWeekSegment): number => {
    let sum = 0;
    let d = parseIsoDateLocal(seg.from);
    for (let i = 0; i < seg.days; i += 1) {
      sum += realizadoPorDia.get(toIsoDateLocal(d)) ?? 0;
      d = addDays(d, 1);
    }
    return sum;
  };

  let committed = 0;
  let daysRemaining = segments.reduce((s, seg) => s + seg.days, 0);
  const out: TvWeeklyGoal[] = [];
  for (const seg of segments) {
    const target =
      daysRemaining > 0 ? ((metaMensal - committed) * seg.days) / daysRemaining : 0;
    const isPast = seg.to < todayIso;
    const isCurrent = seg.from <= todayIso && todayIso <= seg.to;
    const achieved = isPast || isCurrent ? sumSegment(seg) : null;
    out.push({ segment: seg, target, achieved, isCurrent });
    // Passadas comprometem o REAL (déficit/superávit redistribui);
    // corrente/futuras comprometem o TARGET (projeção on-target).
    committed += isPast ? (achieved ?? 0) : target;
    daysRemaining -= seg.days;
  }
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Curva horária (R5) + projeção de fim de mês (R3)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Base "ontem até a MESMA hora" usando a curva horária REAL do dia de
 * referência: `prevDayTotal × (cumulativo de prevDayByHour até HH:mm ÷
 * cumulativo total)`. A hora corrente entra com fração linear do minuto
 * dentro da hora (15:30 → metade do bucket "15").
 *
 * A curva é usada APENAS como fração (kits têm valorUnitario 0 na fonte) —
 * o valor absoluto vem sempre do total oficial `prevDayTotal`.
 *
 * Retorna null quando não há base honesta — curva ausente/vazia, cumulativo
 * total 0, total não positivo ou fração 0 (antes da 1ª venda do dia de
 * referência) — para o caller cair no fallback pró-rata linear existente.
 */
export function hourlyPaceBase(
  prevDayTotal: number,
  prevDayByHour: Record<string, number> | undefined,
  now: Date,
): number | null {
  if (prevDayTotal <= 0 || !prevDayByHour) return null;
  const buckets: Array<[number, number]> = [];
  for (const [hh, value] of Object.entries(prevDayByHour)) {
    const hour = Number(hh);
    if (!Number.isInteger(hour) || hour < 0 || hour > 23) continue;
    buckets.push([hour, value]);
  }
  const cumTotal = buckets.reduce((s, [, v]) => s + v, 0);
  if (cumTotal <= 0) return null;
  const currentHour = now.getHours();
  const minuteFraction = (now.getMinutes() + now.getSeconds() / 60) / 60;
  let cumNow = 0;
  for (const [hour, value] of buckets) {
    if (hour < currentHour) cumNow += value;
    else if (hour === currentHour) cumNow += value * minuteFraction;
  }
  if (cumNow <= 0) return null;
  return prevDayTotal * (cumNow / cumTotal);
}

/**
 * Projeção de fim de mês por run-rate: `mtd ÷ dias decorridos × dias do
 * mês`, com "dias decorridos" = dias COMPLETOS decorridos + 1 (hoje conta
 * inteiro — sem fração de dia, decisão da spec). No dia 1º a projeção é
 * `mtd × diasDoMês` (run-rate de 1 dia).
 */
export function monthEndProjection(mtdTotal: number, now: Date): number {
  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  const daysElapsed = now.getDate();
  return (mtdTotal / daysElapsed) * daysInMonth;
}

