    expect(shiftedPeriodRange('week', 0, now)).toEqual(periodRange('week', now));
    expect(shiftedPeriodRange('month', 0, now)).toEqual(periodRange('month', now));
  });

  it('today: offset -n desloca n dias (dia cheio)', () => {
    expect(shiftedPeriodRange('today', -1, now)).toEqual({
      from: '2026-06-03',
      to: '2026-06-03',
    });
    expect(shiftedPeriodRange('today', -3, now)).toEqual({
      from: '2026-06-01',
      to: '2026-06-01',
    });
  });

  it('week: offset -n = semana seg-dom COMPLETA n semanas atrás', () => {
    expect(shiftedPeriodRange('week', -1, now)).toEqual({
      from: '2026-05-25',
      to: '2026-05-31',
    });
    expect(shiftedPeriodRange('week', -2, now)).toEqual({
      from: '2026-05-18',
      to: '2026-05-24',
    });
  });

  it('month: offset -n = mês-calendário COMPLETO n meses atrás', () => {
    expect(shiftedPeriodRange('month', -1, now)).toEqual({
      from: '2026-05-01',
      to: '2026-05-31',
    });
    // Abril tem 30 dias — limite do mês respeitado (não 31)
    expect(shiftedPeriodRange('month', -2, now)).toEqual({
      from: '2026-04-01',
      to: '2026-04-30',
    });
  });

  it('month: offset -n cruza a virada de ano', () => {
    expect(shiftedPeriodRange('month', -6, now)).toEqual({
      from: '2025-12-01',
      to: '2025-12-31',
    });
  });

  it('offset positivo não navega pro futuro — tratado como 0', () => {
    expect(shiftedPeriodRange('today', 2, now)).toEqual(periodRange('today', now));
  });
});

describe('monthWeekSegments', () => {
  it('mês que começa na segunda (jun/2026): semanas cheias + sobra final', () => {
    const segments = monthWeekSegments(2026, 5); // junho/2026 — seg 01/06
    expect(segments.map((s) => [s.from, s.to, s.days])).toEqual([
      ['2026-06-01', '2026-06-07', 7],
      ['2026-06-08', '2026-06-14', 7],
      ['2026-06-15', '2026-06-21', 7],
      ['2026-06-22', '2026-06-28', 7],
      ['2026-06-29', '2026-06-30', 2], // recorte: última "semana" tem 2 dias
    ]);
    expect(segments.map((s) => s.index)).toEqual([1, 2, 3, 4, 5]);
  });

  it('mês que começa no meio da semana (mai/2026, sexta): 1º segmento curto', () => {
    const segments = monthWeekSegments(2026, 4); // maio/2026 — sex 01/05
    expect(segments[0]).toEqual({
      index: 1,
      from: '2026-05-01',
      to: '2026-05-03',
      days: 3, // sex-dom
    });
    expect(segments[segments.length - 1]).toEqual({
      index: 5,
      from: '2026-05-25',
      to: '2026-05-31',
      days: 7, // termina exatamente num domingo
    });
  });

  it('soma dos dias dos segmentos = dias do mês', () => {
    for (const [year, month, expected] of [
      [2026, 5, 30],
      [2026, 4, 31],
      [2024, 1, 29], // fevereiro bissexto
