});

describe('weeklyTargets (A4 — redistribuição da meta mensal)', () => {
  // qua 10/06/2026 — semana 2 do mês (08-14/06) é a corrente
  const now = new Date(2026, 5, 10, 15, 0, 0);
  const META = 100_000;

  /** Realizado uniforme por dia num intervalo de dias de junho/2026. */
  const realizado = (perDay: number, fromDay: number, toDay: number) => {
    const map = new Map<string, number>();
    for (let d = fromDay; d <= toDay; d += 1) {
      map.set(`2026-06-${String(d).padStart(2, '0')}`, perDay);
    }
    return map;
  };

  it('semana 1 abaixo da meta ⇒ target da semana 2 SOBE (meta mensal fixa)', () => {
    // Target original semana 1 = 100k × 7/30 ≈ 23.333; realizado só 14k
    const weeks = weeklyTargets(META, realizado(2_000, 1, 7), now);
    const originalWeek2 = (META * 7) / 30;
    expect(weeks[0].achieved).toBeCloseTo(14_000, 5);
    expect(weeks[0].target).toBeCloseTo((META * 7) / 30, 2);
    // Semana 2: (100k − 14k) × 7/23 ≈ 26.173,91 > 23.333,33
    expect(weeks[1].target).toBeCloseTo((86_000 * 7) / 23, 2);
    expect(weeks[1].target).toBeGreaterThan(originalWeek2);
  });

  it('semana 1 acima da meta ⇒ target da semana 2 DESCE', () => {
    const weeks = weeklyTargets(META, realizado(40_000 / 7, 1, 7), now);
    expect(weeks[1].target).toBeCloseTo((60_000 * 7) / 23, 2);
    expect(weeks[1].target).toBeLessThan((META * 7) / 30);
  });

  it('invariante: realizado passado + soma dos targets restantes = meta mensal', () => {
    const weeks = weeklyTargets(META, realizado(2_000, 1, 9), now);
    const pastAchieved = weeks
      .filter((w) => !w.isCurrent && w.achieved !== null && w.segment.to < '2026-06-10')
      .reduce((s, w) => s + (w.achieved ?? 0), 0);
    const remainingTargets = weeks
      .filter((w) => w.isCurrent || w.segment.from > '2026-06-10')
      .reduce((s, w) => s + w.target, 0);
    expect(pastAchieved + remainingTargets).toBeCloseTo(META, 5);
  });

  it('achieved: passadas e corrente somam o realizado; futuras = null', () => {
    const weeks = weeklyTargets(META, realizado(1_000, 1, 10), now);
    expect(weeks[0].achieved).toBeCloseTo(7_000, 5); // semana 1 completa
    expect(weeks[1].achieved).toBeCloseTo(3_000, 5); // corrente: dias 08-10
    expect(weeks[1].isCurrent).toBe(true);
    expect(weeks[2].achieved).toBeNull();
    expect(weeks[3].achieved).toBeNull();
    expect(weeks.filter((w) => w.isCurrent)).toHaveLength(1);
  });
});

describe('hourlyPaceBase (A5 — fração horária real, não linear)', () => {
  // Curva sintética com pico no almoço — bem diferente de linear
  const curve: Record<string, number> = {
    '10': 100,
    '11': 100,
    '12': 300,
    '13': 300,
    '14': 100,
    '15': 50,
    '16': 50,
  }; // cumulativo total = 1000

  it('às 15h usa a fração horária REAL de ontem (≠ pró-rata linear)', () => {
    const now = new Date(2026, 5, 4, 15, 0, 0);
    // cumulativo até 15h = 900/1000 = 0.9 → base 2000 × 0.9 = 1800
    const base = hourlyPaceBase(2_000, curve, now);
    expect(base).toBeCloseTo(1_800, 5);
    // Pró-rata linear às 15h (janela 10-22) seria 2000 × 5/12 ≈ 833 — bem menor
    const linear = proRataDayBase(2_000, now);
    expect(linear).toBeCloseTo(2_000 * (5 / 12), 5);
    expect(base).not.toBeCloseTo(linear ?? 0, 0);
  });

  it('interpola a fração do minuto dentro da hora corrente', () => {
    // 15:30 → bucket "15" entra pela metade: (900 + 25)/1000 = 0.925
    const base = hourlyPaceBase(2_000, curve, new Date(2026, 5, 4, 15, 30, 0));
    expect(base).toBeCloseTo(1_850, 5);
  });

  it('depois da última hora da curva usa o dia inteiro (fração 1)', () => {
    const base = hourlyPaceBase(2_000, curve, new Date(2026, 5, 4, 23, 0, 0));
    expect(base).toBeCloseTo(2_000, 5);
  });

  it('sem base honesta → null (caller cai no fallback linear)', () => {
    const now = new Date(2026, 5, 4, 15, 0, 0);
    expect(hourlyPaceBase(2_000, undefined, now)).toBeNull(); // curva ausente
    expect(hourlyPaceBase(2_000, {}, now)).toBeNull(); // curva vazia
    expect(hourlyPaceBase(2_000, { '10': 0, '11': 0 }, now)).toBeNull(); // cum 0
    expect(hourlyPaceBase(0, curve, now)).toBeNull(); // total não positivo
    // Antes da 1ª venda de ontem (fração 0) também não há comparação honesta
    expect(hourlyPaceBase(2_000, curve, new Date(2026, 5, 4, 8, 0, 0))).toBeNull();
  });

  it('ignora chaves de hora malformadas sem corromper a fração', () => {
    const base = hourlyPaceBase(
      1_000,
      { '10': 500, junk: 9_999, '25': 9_999, '12': 500 },
      new Date(2026, 5, 4, 11, 0, 0),
    );
    // Só "10" e "12" valem: cumulativo até 11h = 500/1000 → 500
    expect(base).toBeCloseTo(500, 5);
  });
});

describe('monthEndProjection (run-rate)', () => {
  it('mtd ÷ dias decorridos (hoje conta inteiro) × dias do mês', () => {
    // 10/06: 50k ÷ 10 × 30 = 150k
    expect(monthEndProjection(50_000, new Date(2026, 5, 10, 15))).toBeCloseTo(
