/** Chamada única à edge `degust-pos-financial` (todos os fetchers Degust). */
async function callDegustEdge(
  body: DegustPosFinancialBody,
): Promise<DegustPosFinancialResponse> {
  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
  const anonKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string;
  const session = (await supabase.auth.getSession()).data.session;
  const token = session?.access_token ?? anonKey;

  const resp = await fetch(`${supabaseUrl}/functions/v1/degust-pos-financial`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
      apikey: anonKey,
    },
    body: JSON.stringify(body),
  });

  if (!resp.ok) {
    throw new Error(`[tv-dashboard] degust-pos-financial: HTTP ${resp.status}`);
  }
  return (await resp.json()) as DegustPosFinancialResponse;
}

