// ─────────────────────────────────────────────────────────────────────────────
// Modo histórico (offset < 0): vendas oficiais de um range passado (R2)
// ─────────────────────────────────────────────────────────────────────────────

/** Vendas oficiais (ticket-medio) por loja × data de um range PASSADO. */
interface RangeSalesResult {
  /** loja_id → data → R$ total oficial do dia. */
  dailyByLoja: Map<number, Map<string, number>>;
  /** loja_id → data → cupons do dia. */
  cuponsByLoja: Map<number, Map<string, number>>;
}

/**
 * Busca os totais oficiais por dia para o modo passado, numa ÚNICA chamada
 * cobrindo `[from, to]` — o caller passa `previousRange.from → range.to`
 * (ranges equivalentes consecutivos são contíguos por construção).
 */
async function fetchRangeSales(
  ctx: TvContext,
  from: string,
  to: string,
): Promise<RangeSalesResult> {
  const data = await callDegustEdge({ startDate: from, endDate: to });
  const dailyByLoja = new Map<number, Map<string, number>>();
  const cuponsByLoja = new Map<number, Map<string, number>>();
  for (const d of data.daily ?? []) {
    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
    let valores = dailyByLoja.get(d.loja_id);
    if (!valores) {
      valores = new Map<string, number>();
      dailyByLoja.set(d.loja_id, valores);
    }
    valores.set(d.data, (valores.get(d.data) ?? 0) + (d.total_faturado ?? 0));
    let cupons = cuponsByLoja.get(d.loja_id);
    if (!cupons) {
      cupons = new Map<string, number>();
      cuponsByLoja.set(d.loja_id, cupons);
    }
    cupons.set(d.data, (cupons.get(d.data) ?? 0) + (d.total_cupons ?? 0));
  }
  return { dailyByLoja, cuponsByLoja };
}

/**
 * Soma os valores de um mapa data→R$ dentro de um range fechado [from, to].
 * `daysWithData` distingue "vendeu R$ 0" de "sem dado nenhum" (vendas null).
 */
function sumRange(
  byDate: Map<string, number> | undefined,
  range: TvDateRange,
): { total: number; daysWithData: number } {
  if (!byDate) return { total: 0, daysWithData: 0 };
  let total = 0;
  let daysWithData = 0;
  let d = parseIsoDateLocal(range.from);
  const end = parseIsoDateLocal(range.to).getTime();
  while (d.getTime() <= end) {
    const v = byDate.get(toIsoDateLocal(d));
    if (v != null) {
      total += v;
      daysWithData += 1;
    }
    d = addDays(d, 1);
  }
  return { total, daysWithData };
}

/** Dias FECHADOS de um range [from, to] (DST-safe via Math.round). */
function rangeDayCount(range: TvDateRange): number {
  const from = parseIsoDateLocal(range.from).getTime();
  const to = parseIsoDateLocal(range.to).getTime();
  return Math.round((to - from) / 86_400_000) + 1;
}

// ─────────────────────────────────────────────────────────────────────────────
// Acumulado do mês (R3): 01 → hoje via ticket-medio
// ─────────────────────────────────────────────────────────────────────────────

/** MTD da rede: total por DATA (rede) + total por LOJA. */
interface MtdSalesResult {
  /** data (YYYY-MM-DD) → R$ da REDE no dia (lojas Degust somadas). */
  byDate: Map<string, number>;
  /** loja_id → R$ acumulado no mês. */
  byLoja: Map<number, number>;
}

async function fetchMtdSales(ctx: TvContext): Promise<MtdSalesResult> {
  const now = new Date();
  const from = toIsoDateLocal(new Date(now.getFullYear(), now.getMonth(), 1));
  const to = toIsoDateLocal(now);
  const data = await callDegustEdge({ startDate: from, endDate: to });
  const byDate = new Map<string, number>();
  const byLoja = new Map<number, number>();
  for (const d of data.daily ?? []) {
    if (!ctx.degustLojaIds.has(d.loja_id)) continue;
    const valor = d.total_faturado ?? 0;
    byDate.set(d.data, (byDate.get(d.data) ?? 0) + valor);
    byLoja.set(d.loja_id, (byLoja.get(d.loja_id) ?? 0) + valor);
  }
  return { byDate, byLoja };
}

