// Curvas horárias ontem+hoje (R5) e quebra delivery (R1)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchHourlyCurves(): Promise<TvHourlyCurve[]> {
  const now = new Date();
  const yesterday = toIsoDateLocal(addDays(now, -1));
  const today = toIsoDateLocal(now);
  const data = await callDegustEdge({
    startDate: yesterday,
    endDate: today,
    includeHourly: true,
    hourlyDates: [yesterday, today],
  });
  return (data.hourly ?? []).map((h) => ({
    lojaId: h.loja_id,
    data: h.data,
    byHour: h.byHour,
  }));
}

/**
 * Quebra delivery×balcão de UM dia (a data exibida: hoje no live, dia
 * selecionado no modo passado). null quando o dia não tem cupom delivery.
 */
async function fetchDeliverySplitDay(date: string): Promise<TvDeliverySplit | null> {
  const data = await callDegustEdge({
    startDate: date,
    endDate: date,
    includeDeliverySplit: true,
    deliveryLojaId: TV_DELIVERY_SPLIT_LOJA_ID,
  });
  const row = (data.deliverySplit ?? []).find((r) => r.data === date);
  if (!row) return null;
  return {
    lojaId: row.loja_id,
    data: row.data,
    totalDelivery: row.total_delivery,
    cuponsDelivery: row.cupons_delivery,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Metas mensais (R4): `metas_mensais` do mês corrente
// ─────────────────────────────────────────────────────────────────────────────

async function fetchMetasMensais(now: Date): Promise<TvMetaMensal[]> {
  const { data, error } = await supabase
    .from('metas_mensais')
    .select('loja_id, ano, mes, valor_meta')
    .eq('ano', now.getFullYear())
    .eq('mes', now.getMonth() + 1);
  if (error) {
    // Tolerar ambiente onde a migration ainda não rodou (tabela ausente):
    // painel segue sem meta mensal em vez de derrubar o snapshot inteiro.
    console.error('[tv-dashboard] metas_mensais indisponível:', error.message);
    return [];
  }
  return (data ?? []).map((row) => ({
    lojaId: row.loja_id,
    ano: row.ano,
    mes: row.mes,
    valorMeta: row.valor_meta,
  }));
}

