 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
 * `freshness`, `monthProgress`). Vendas live re-buscam a cada 60s; o
 * resto a cada 5min (com invalidação antecipada via {@link useTvRealtime}).
 *
 * @param period - Filtro global Hoje/Semana/Mês — muda perdas, compras e
 *   seus comparativos. No modo live, vendas dos cards são SEMPRE de hoje.
 * @param offset - Navegação no histórico (R2): 0 = ao vivo; −n = período
 *   COMPLETO n posições atrás (dia/semana/mês conforme `period`). Com
 *   offset < 0 o polling de 60s e o flash são DESLIGADOS — vendas vêm do
 *   total oficial (ticket-medio) do range deslocado e os deltas comparam
 *   períodos completos (sem pró-rata).
 */
export function useTvDashboardData(
  period: TvPeriod = 'today',
  offset = 0,
): TvDashboardData {
  // "now" que AVANÇA (tick de minuto): staleness/RAG/pró-rata reclassificam
  // mesmo quando NENHUMA query devolve dado novo (outage total). Sem isso o
  // chip ficaria "✓ ao vivo" pra sempre com tudo fora do ar.
  const tick = useMinuteClock();

  // Offset positivo não existe (não há futuro a navegar) — clamp em 0.
  const clampedOffset = Math.min(0, Math.trunc(offset));
  const isLive = clampedOffset === 0;
  // Ranges calculados FORA do useMemo: entram em query keys e fetchers.
  // No modo passado o "anterior equivalente" é o período COMPLETO
  // imediatamente antes (sem pró-rata); no live mantém a semântica v3.
  const range = shiftedPeriodRange(period, clampedOffset, tick);
  const previousRange = isLive
    ? previousPeriodRange(period, tick)
    : shiftedPeriodRange(period, clampedOffset - 1, tick);

  const ctxQuery = useQuery({
    queryKey: tvDashboardKeys.context(),
    queryFn: fetchTvContext,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });
  const ctx = ctxQuery.data;

  const liveQuery = useQuery({
    queryKey: tvDashboardKeys.liveSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchLiveSales(ctx);
    },
    // Modo passado NÃO faz polling de 60s nem usa flash (R2)
    enabled: !!ctx && isLive,
    refetchInterval: TV_QUERY_INTERVALS.liveMs,
    staleTime: 30_000,
  });

  // Vendas oficiais do range deslocado (modo passado) — uma chamada cobre
  // o range exibido + o anterior equivalente (contíguos por construção).
  const rangeQuery = useQuery({
    queryKey: tvDashboardKeys.rangeSales(range, previousRange),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchRangeSales(ctx, previousRange.from, range.to);
    },
    enabled: !!ctx && !isLive,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const laggedQuery = useQuery({
    queryKey: tvDashboardKeys.laggedSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchLaggedSales(ctx);
    },
    // historico_vendas (Linx) parou em abr/2026 — só faz sentido no live
    enabled: !!ctx && isLive,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const referenceQuery = useQuery({
    queryKey: tvDashboardKeys.referenceSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchDegustReference(ctx);
    },
    enabled: !!ctx && isLive,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  // Acumulado do mês corrente (R3) — independe do período/offset exibido.
  const mtdQuery = useQuery({
    queryKey: tvDashboardKeys.mtdSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchMtdSales(ctx);
    },
    enabled: !!ctx,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  // Curvas horárias ontem+hoje (R5) — só no live (base do delta vs ontem).
  const hourlyQuery = useQuery({
    queryKey: tvDashboardKeys.hourlyCurves(),
    queryFn: fetchHourlyCurves,
    enabled: !!ctx && isLive,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  // Quebra delivery do dia exibido (R1) — apenas período "hoje" (live ou
  // dia passado); a quebra não se aplica a agregados de semana/mês.
  const deliveryDate = range.to;
  const deliveryQuery = useQuery({
    queryKey: tvDashboardKeys.deliverySplit(deliveryDate),
    queryFn: () => fetchDeliverySplitDay(deliveryDate),
    enabled: !!ctx && period === 'today',
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  // Metas mensais do mês corrente (R4) — tolera tabela ausente ([]).
  const metasMensaisQuery = useQuery({
    queryKey: tvDashboardKeys.metasMensais(),
    queryFn: () => fetchMetasMensais(new Date()),
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const perdasQuery = useQuery({
    queryKey: tvDashboardKeys.perdas(period, clampedOffset),
    queryFn: () => fetchPerdasAggregates(range, previousRange),
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const marketingQuery = useQuery({
    queryKey: tvDashboardKeys.marketing(period, clampedOffset),
    queryFn: () => fetchMarketingAggregates(range, previousRange),
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

