const businessFraction = businessDayFraction(now);
const horasDecorridas = isLive
  ? businessFraction * 12 // janela 10h–22h = 12h
  : 12 * rangeDayCount(range);
const valorPorHora = horasDecorridas > 0 && vendasHoje > 0
  ? vendasHoje / horasDecorridas
  : null;
const vendasPorHora = horasDecorridas > 0 && totalCupons > 0
  ? totalCupons / horasDecorridas
  : null;
const metasHoje = liveStores
  .map((s) => s.metaDia)
  .filter((m): m is number => m != null && m > 0);
const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;

// Base do delta principal:
// - live: soma por loja do "dia anterior ao flash" PACEADO pela curva
//   horária real (R5) — fallback dia completo quando não há curva;
// - passado: total oficial do período equivalente anterior COMPLETO.
const prevNetworkBase = isLive
  ? liveStores.reduce((sum, st) => {
      const flash = flashByLoja.get(st.lojaId);
      if (!flash) return sum;
      const ft = parseBrDateTime(flash.ultima_atualizacao);
      const fd = ft ? toIsoDateLocal(ft) : todayIso;
      const pd = toIsoDateLocal(addDays(parseIsoDateLocal(fd), -1));
      const prevVal =
        dailyByLoja.get(st.lojaId)?.get(pd) ?? yesterdayByLoja.get(st.lojaId) ?? 0;
      if (prevVal <= 0) return sum;
      const pace = hourlyPaceBase(
        prevVal,
        hourlyByKey.get(`${st.lojaId}:${pd}`),
        now,
      );
      return sum + (pace ?? prevVal);
    }, 0)
  : liveStores.reduce(
      (sum, st) =>
        sum + sumRange(rangeData?.dailyByLoja.get(st.lojaId), previousRange).total,
      0,
    );

metaDia,
// Live: pró-rata da janela; passado dia: % do dia COMPLETO;
// passado semana/mês: sem meta agregada honesta → null.
pctMetaProRata: isLive
  ? pctOfProRataTarget(vendasHoje, metaDia, now)
  : period === 'today'
    ? pctOfFullDayTarget(vendasHoje, metaDia)
    : null,
// deltaSemana: só no live com period='week'
deltaSemana: isLive && period === 'week'
  ? weekOverWeekDelta(
      vendasHoje,
      proRataDayBase(lastWeekTotal, now) ?? (lastWeekTotal || null),
    )
  : null,
// deltaOntem: live = vs dia anterior ao flash (base paceada);
// passado = vs período equivalente anterior completo
deltaOntem: relativeDelta(vendasHoje, prevNetworkBase || null),

    // ── Mês até agora (R3) + meta mensal com semanas redistribuídas (R4) ──
    // Sempre o mês CORRENTE, independente do período/offset exibido.
    let monthProgress: TvMonthProgress | null = null;
    const mtd = mtdQuery.data;
    if (mtd) {
      let mtdTotal = 0;
      for (const valor of mtd.byDate.values()) mtdTotal += valor;
      const metasMensais = metasMensaisQuery.data ?? [];
      const redeRow = metasMensais.find((m) => m.lojaId === null);
      const lojaRows = metasMensais.filter((m) => m.lojaId !== null);
      // Meta da rede: linha loja_id NULL; fallback = soma das metas por loja
      const metaMensal =
        redeRow != null
          ? redeRow.valorMeta
          : lojaRows.length > 0
            ? lojaRows.reduce((s, m) => s + m.valorMeta, 0)
            : null;
      const weeks =
        metaMensal != null && metaMensal > 0
          ? weeklyTargets(metaMensal, mtd.byDate, now)
          : [];
      monthProgress = {
        mtdTotal,
        metaMensal,
        pctMeta:
          metaMensal != null && metaMensal > 0
            ? (mtdTotal / metaMensal) * 100
            : null,
        projection: monthEndProjection(mtdTotal, now),
        weeks,
        currentWeek: weeks.find((w) => w.isCurrent) ?? null,
        mtdByLoja: mtd.byLoja,
      };
    }

    return {
      network,
      stores,
      factory,
      exceptions,
      freshness,
      period,
      offset: clampedOffset,
      isLive,
      range,
      previousRange,
      monthProgress,
      deliverySplitToday: deliveryData,
      hourlyCurves: hourlyQuery.data ?? [],
      isLoading: ctxQuery.isLoading,
      isError: ctxQuery.isError,
    };
  }, [
    // `tick` é o que faz staleness/RAG avançarem em outage total (sem ele a
    // classificação congelaria no último snapshot de dados).
    tick,
    period,
    clampedOffset,
    isLive,
    // Ranges são objetos novos a cada render — depender das STRINGS evita
    // recomputar o snapshot sem mudança real de período.
    range.from,
    range.to,
    previousRange.from,
    previousRange.to,
    ctx,
    ctxQuery.isLoading,
    ctxQuery.isError,
    liveQuery.data,
    liveQuery.dataUpdatedAt,
    rangeQuery.data,
    rangeQuery.dataUpdatedAt,
    laggedQuery.data,
    referenceQuery.data,
    metasQuery.data,
    metasMensaisQuery.data,
    mtdQuery.data,
    hourlyQuery.data,
    deliveryQuery.data,
    stockQuery.data,
    stockQuery.dataUpdatedAt,
    movementsQuery.data,
    feedQuery.data,
    perdasQuery.data,
    marketingQuery.data,
    factoryQuery.data,
  ]);
}

